insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-07-21','nieuw','Dossiers','Acties van een dossier zichtbaar op je telefoon',
   'Open je een dossier in de app, dan zie je onder Info nu een blok Acties met de vijf eerstvolgende openstaande acties, met de datum waarop ze klaar moeten zijn en wie ze heeft. De rest en alles wat al afgerond is klap je uit met één knop.'),
  ('2026-07-21','verbeterd','Platform','Niet meer uitgelogd worden terwijl je aan het werk bent',
   'De app logde je uit zodra je een kwartier niets had aangeraakt, wat bij werk op locatie steeds opnieuw inloggen betekende. Voortaan blijf je de hele werkdag ingelogd en logt de app aan het eind van de dag één keer uit, zodat je ''s ochtends opnieuw inlogt.');
